def binary_search(arr, x):
    # Check if the array is empty
    if len(arr) == 0:
        return -1

    # Check if the element is at the beginning or end of the array
    if arr[0] == x:
        return 0
    elif arr[-1] == x:
        return len(arr) - 1

    # Find the middle index
    mid = len(arr) // 2

    # Check if the element is in the middle of the array
    if arr[mid] == x:
        return mid

    # Check if the element is greater than the middle element
    if arr[mid] < x:
        return binary_search(arr[mid:], x)

    # Check if the element is less than the middle element
    else:
        return binary_search(arr[:mid], x)
```
